#include <vector>
#include <omp.h>

double productWithInverses(std::vector<double> const& x) {
    double result = 1.0;

    #pragma omp parallel for reduction(*:result)
    for (std::size_t i = 0; i < x.size(); ++i) {
        if ((i & 1u) == 0u) {
            result *= x[i];
        } else {
            result *= 1.0 / x[i];
        }
    }

    return result;
}
